import{_ as n,o as a,c as d,a3 as e}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"UI/UX Specification — AnPhucRealEstate v1 (Web)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/05-ui-ux-spec.md","filePath":"guide/05-ui-ux-spec.md","lastUpdated":null}'),i={name:"guide/05-ui-ux-spec.md"};function o(s,t,r,c,h,l){return a(),d("div",null,[...t[0]||(t[0]=[e(`<h1 id="ui-ux-specification-—-anphucrealestate-v1-web" tabindex="-1">UI/UX Specification — AnPhucRealEstate v1 (Web) <a class="header-anchor" href="#ui-ux-specification-—-anphucrealestate-v1-web" aria-label="Permalink to &quot;UI/UX Specification — AnPhucRealEstate v1 (Web)&quot;">​</a></h1><p><strong>Status</strong>: Draft chờ Design Lead — <strong>Author</strong>: Alex (PM) + Design Lead (Figma TBD) — <strong>Updated</strong>: 2026-10-09 — <strong>v1.1</strong> (review pass: SC-09 thêm link &quot;Quên mật khẩu?&quot; → hướng dẫn CS, đồng bộ tiền/múi giờ/khung giờ với docs/02/08) <strong>Figma</strong>: link chưa tồn tại — <strong>điều kiện bắt buộc trước dev MS1</strong>: <code>https://figma.com/&lt;TBD&gt;</code> (OQ-design-1). Quy ước của doc này: <strong>mọi màn phải có chú thích hành vi trong Figma</strong>, không chỉ hình — khung chú thích dùng nội dung §3/§4 dưới đây (copy nguyên văn ID SC-xx để trace).</p><h2 id="_1-nguyen-tac-thiet-ke" tabindex="-1">1. Nguyên tắc thiết kế <a class="header-anchor" href="#_1-nguyen-tac-thiet-ke" aria-label="Permalink to &quot;1. Nguyên tắc thiết kế&quot;">​</a></h2><ol><li>Tiếng Việt, văn phong &quot;an toàn &amp; minh bạch&quot; (không màuSale lòe); format tiền <code>1.250.000.000 ₫</code>, ngày <code>dd/MM/yyyy HH:mm</code> ( múi giờ máy khách, gắn chú &quot;GMT+7&quot;).</li><li>Mobile-first responsive; breakpoints <strong>360 / 768 / 1024 / 1440</strong>; table admin ưu tiên desktop.</li><li>Mọi CTA nghiệp vụ phải hiện <strong>đủ trạng thái: default / loading (disabled) / success / error</strong> — FE dùng component <code>Button</code> với <code>loading</code> prop.</li><li>Pattern 4 trạng thái bắt buộc cho mọi màn dữ liệu: <strong>Loading (skeleton) → Empty (CTA hướng dẫn) → Error (thông điệp + nút thử lại, kèm traceId rút gọn) → Data</strong>.</li><li>Form: validate onBlur + onSubmit, message <strong>tại field</strong>, dùng string từ <code>docs/06 §5</code> (một nguồn lỗi).</li><li>Tiền là thông tin trọng yếu: mọi màn có tiền hiện <strong>breakdown từng dòng</strong>, không hiện số gộp duy nhất.</li><li>Accessibility: contrast AA, focus ring, label cho mọi input, alt text ảnh tin.</li></ol><h2 id="_2-information-architecture-navigation" tabindex="-1">2. Information Architecture &amp; Navigation <a class="header-anchor" href="#_2-information-architecture-navigation" aria-label="Permalink to &quot;2. Information Architecture &amp; Navigation&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/(public)</span></span>
<span class="line"><span>  ├─ /                      Trang chủ SC-01</span></span>
<span class="line"><span>  ├─ /nha-o-xa-hoi          Danh sách tin SC-02</span></span>
<span class="line"><span>  ├─ /nha-o-xa-hoi/[id]     Chi tiết tin SC-03</span></span>
<span class="line"><span>  ├─ /du-an/[id]            Chi tiết dự án SC-04</span></span>
<span class="line"><span>  ├─ /dau-gia               Danh sách phiên SC-05</span></span>
<span class="line"><span>  ├─ /dau-gia/[id]          Chi tiết / Live phiên SC-06</span></span>
<span class="line"><span>  ├─ /bang-goi              Bảng gói VIP SC-07</span></span>
<span class="line"><span>  ├─ /hoi-dap               Static guide SC-08</span></span>
<span class="line"><span>/(auth)  /dang-nhap SC-09 · /dang-ky SC-10</span></span>
<span class="line"><span>/(user)  — guard USER</span></span>
<span class="line"><span>  ├─ /dashboard             SC-20</span></span>
<span class="line"><span>  ├─ /xac-minh              KYC SC-21</span></span>
<span class="line"><span>  ├─ /dang-ban              wizard SC-22 (+ /[id] sửa)</span></span>
<span class="line"><span>  ├─ /tin-cua-toi           SC-23 (+ /[id] chi tiết quản trị)</span></span>
<span class="line"><span>  ├─ /dau-gia/toi           đăng ký+cọc SC-24</span></span>
<span class="line"><span>  ├─ /don-cua-toi           orders SC-25</span></span>
<span class="line"><span>  ├─ /goi-cua-toi           subscription SC-26</span></span>
<span class="line"><span>  ├─ /lich-xem-nha          SC-27 (2 tab: đã yêu cầu / đã nhận)</span></span>
<span class="line"><span>  ├─ /thong-bao             SC-28</span></span>
<span class="line"><span>  └─ /ho-so                 SC-29</span></span>
<span class="line"><span>/(admin) — guard ADMIN, layout riêng</span></span>
<span class="line"><span>  /admin/dashboard SC-40 · /admin/kyc SC-41 · /admin/tin SC-42</span></span>
<span class="line"><span>  /admin/du-an SC-43 · /admin/dau-gia SC-44 (+create SC-45, +[id] monitor SC-46)</span></span>
<span class="line"><span>  /admin/thanhtoan SC-47 · /admin/nguoi-dung SC-48 · /admin/audit SC-49</span></span></code></pre></div><p><strong>Quy tắc điều hướng</strong>: deep-link return sau login (AF-1 UC-03); role thay đổi (suspend) → FE bắt 401/403 → logout về <code>/dang-nhap</code> kèm banner lý do; admin không lẫn menu user (layout riêng).</p><h2 id="_3-screen-inventory-behavior-notes-man-chinh" tabindex="-1">3. Screen Inventory + Behavior Notes (màn chính) <a class="header-anchor" href="#_3-screen-inventory-behavior-notes-man-chinh" aria-label="Permalink to &quot;3. Screen Inventory + Behavior Notes (màn chính)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Màn</th><th>Thành phần</th><th>Hành vi / validation chính</th><th>States</th><th>Trống/rỗng</th></tr></thead><tbody><tr><td>SC-01</td><td>Trang chủ</td><td>Hero + search, 6 tin mới, 3 phiên sắp mở (countdown), CTA &quot;Đăng bán&quot;</td><td>Search điều hướng SC-02 với query; CTA Guest→SC-10 intent</td><td>skeleton</td><td>&quot;Chưa có tin — xem dự án&quot;</td></tr><tr><td>SC-02</td><td>Danh sách tin</td><td>Filter rail (dự án, giá min/max, diện tích, sort), card grid + pagination</td><td>URL sync query (shareable); sort default newest; <code>featured</code> = VIP trước (badge sao)</td><td>skeleton/error/retry</td><td>&quot;Không tìm thấy&quot; + clear filters</td></tr><tr><td>SC-03</td><td>Chi tiết tin</td><td>Gallery (lightbox), thông số, giá+đơn giá m², dự án map-placeholder, chủ (ẩn danh: &quot;Chủ nhà đã xác minh ✓&quot;), CTA</td><td>Guest CTA→login-intent; KYC!=APPROVED CTA→SC-21; RESERVED → link SC-06; chủ tin thấy tab quản trị + certSerial masked</td><td>404 page &quot;tin không khả dụng&quot;</td><td>—</td></tr><tr><td>SC-04</td><td>Chi tiết dự án</td><td>Info + cap giá/m², list tin cùng dự án</td><td>—</td><td>empty</td><td>—</td></tr><tr><td>SC-05</td><td>Danh sách phiên</td><td>Tabs upcoming/live/ended; card countdown + openingPrice</td><td>live có pulse đỏ; pagination</td><td>empty</td><td>—</td></tr><tr><td>SC-06</td><td>Phiên live</td><td>See §4</td><td>§4</td><td>—</td><td>—</td></tr><tr><td>SC-07</td><td>Bảng gói</td><td>3 pricing cards, so sánh quyền lợi, FAQ</td><td>Nút Guest→login; FREE disabled</td><td>—</td><td>—</td></tr><tr><td>SC-08</td><td>Hướng dẫn</td><td>Static: điều kiện NOXH, quy chế đấu giá, cọc</td><td>—</td><td>—</td><td>—</td></tr><tr><td>SC-09/10</td><td>Login/Register</td><td>Form, show/hide pw, strength meter khi register</td><td>Lỗi server map §5; rate-limit 429 → countdown 15&#39;; redirect intent; SC-09 có link &quot;Quên mật khẩu?&quot; → popover hướng dẫn gọi CS hotline (v1 không self-reset, UC-01 AF-3)</td><td>loading/disable</td><td>—</td></tr><tr><td>SC-20</td><td>Dashboard</td><td>Checklist &quot;bắt đầu&quot; (KYC→tin→VIP), widget: tin của tôi, phiên đã đăng ký, order chờ, notifications gần đây</td><td>CTA theo trạng thái KYC</td><td>skeleton</td><td>onboarding empty</td></tr><tr><td>SC-21</td><td>KYC</td><td>3 step: nhập CCCD/DOB → upload 2 mặt (crop preview) → confirm</td><td>chỉ 12 số; 2 ảnh bắt buộc; xem kỹ cảnh báo dữ liệu nhạy cảm (NĐ13)</td><td>PENDING lock, REJECTED banner reason, APPROVED badge</td><td>retry limit EF-3 UC-02</td></tr><tr><td>SC-22</td><td>Wizard tin</td><td>5 bước (UC-05), progress, autosave DRAFT localStorage+server</td><td>từng bước validate; bước giá hiện cap dự án realtime; bước sổ: check claim realtime (debounce 500ms)</td><td>submit 409/422 inline; quota→modal VIP</td><td>—</td></tr><tr><td>SC-23</td><td>Tin của tôi</td><td>Table tabs theo status, action: sửa / rút / xem lịch sử duyệt</td><td>sửa chỉ khi DRAFT/REJECTED; rút confirm dialog</td><td>empty→CTA đăng tin</td><td>—</td></tr><tr><td>SC-24</td><td>Đăng ký phiên</td><td>Quy chế modal (scroll bắt buộc), deposit amount, chọn kênh (VNPay/manual bill instructions + copy)</td><td>poll trạng thái payment 5s sau redirect; manual hiện &quot;chờ ADMIN xác nhận&quot;</td><td>reg closed; privilege suspended banner</td><td>—</td></tr><tr><td>SC-25</td><td>Orders</td><td>Card per order: breakdown, đồng hồ 24h, nút pay, history status</td><td>hết hạn → trạng thái EXPIRED giải thích forfeit</td><td>COMPLETED thank-you + hướng dẫn CS</td><td>—</td></tr><tr><td>SC-26</td><td>Gói của tôi</td><td>current plan + endsAt, upgrade cards, usage X/limit</td><td>confirm dialog mất phần còn lại</td><td>ACTIVE/EXPIRED variants</td><td>—</td></tr><tr><td>SC-27</td><td>Lịch xem</td><td>2 tab; picker chặn &lt;24h, ngoài 08–20h</td><td>owner: confirm/reject(reason)/complete</td><td>limit 3</td><td>—</td></tr><tr><td>SC-28</td><td>Notifications</td><td>List + unread badge (header bell), mark read/all</td><td>click → deep-link entity</td><td>empty</td><td></td></tr><tr><td>SC-29</td><td>Hồ sơ</td><td>Info edit (tên/SĐT/avatar), đổi mật khẩu</td><td>email readonly</td><td>—</td><td></td></tr><tr><td>SC-40..49</td><td>Admin</td><td>Pattern chung: DataTable server-side (filter/sort/page), drawer chi tiết, action confirm có reason bắt buộc, SLA badge quá hạn</td><td>mọi mutation → toast + audit log; export CSV</td><td>—</td><td></td></tr></tbody></table><h2 id="_4-sc-06-—-phien-đau-gia-live-đac-ta-chi-tiet-man-quan-trong-nhat" tabindex="-1">4. SC-06 — Phiên đấu giá live (đặc tả chi tiết, màn quan trọng nhất) <a class="header-anchor" href="#_4-sc-06-—-phien-đau-gia-live-đac-ta-chi-tiet-man-quan-trong-nhat" aria-label="Permalink to &quot;4. SC-06 — Phiên đấu giá live (đặc tả chi tiết, màn quan trọng nhất)&quot;">​</a></h2><p><strong>Layout desktop</strong>: trái = feed bid (virtualized), phải = sticky panel {listing summary, countdown, current price, leader badge, bid form}. Mobile: tab Feed / Bid, countdown sticky top. <strong>Nguồn dữ liệu v1</strong>: polling <code>GET /auctions/{id}</code> + <code>GET /auctions/{id}/bids?cursor=</code> mỗi <strong>5 giây</strong> (quyết định v1; WebSocket = v1.1, không phụ thuộc UX). Optimistic UI: bid 201 → chèn ngay dòng &quot;Bạn&quot; màu highlight; nếu poll sau đó không thấy (hiếm, race) → FE refresh toàn bộ feed, log Sentry. <strong>Bid form</strong>: quick buttons [+step, +2×step, +5×step] + custom input (số, format VND); min = current+step (client calc từ state server, server re-check). Submit → modal xác nhận &quot;Giá: X — không thể rút. Xác nhận?&quot; → POST. <strong>Countdown</strong>: server time hiệu chỉnh 1 lần (offset = serverDate − clientDate); khi extend anti-snipe → toast đỏ + countdown +60s + dòng hệ thống trong feed &quot;⏱ Phiên kéo dài 60s&quot;. <strong>Kết thúc</strong>: feed khóa (disabled), overlay kết quả: AWARDED (chúc mừng / bạn bị vượt / người TV-XXXX) hoặc FAILED (tin về bán thường, hướng dẫn mua thỏa thuận qua lịch xem). <strong>Trạng thái lỗi</strong>: 429 → &quot;Chờ 1 giây trước khi bid lại&quot; (disable 1s); 403 (bị đuổi) → overlay &quot;Tài khoản tạm ngưng quyền đấu giá — liên hệ CS&quot;; mất kết nối &gt;15s → banner vàng &quot;Mất kết nối — thử lại&quot;, nút bid disable.</p><h2 id="_5-behavior-matrix-nut-chinh-→-api-→-he-qua-ui" tabindex="-1">5. Behavior Matrix: nút chính → API → hệ quả UI <a class="header-anchor" href="#_5-behavior-matrix-nut-chinh-→-api-→-he-qua-ui" aria-label="Permalink to &quot;5. Behavior Matrix: nút chính → API → hệ quả UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nút</th><th>API</th><th>Thành công</th><th>Thất bại</th></tr></thead><tbody><tr><td>Đăng ký (SC-10)</td><td>POST /auth/register</td><td>toast + auto-login → SC-20</td><td>field errors / 409 email</td></tr><tr><td>Gửi duyệt tin (SC-22)</td><td>POST /housing/{id}/submit</td><td>status IN_REVIEW + timeline</td><td>quota → VIP modal; cert claim → dialog CS</td></tr><tr><td>Approve/Reject (SC-42)</td><td id="">PATCH /admin/housing/</td><td>row biến mất queue + toast</td><td>409 đã xử lý → refresh queue + info người duyệt</td></tr><tr><td>Xác nhận cọc manual (SC-47)</td><td id="">PATCH /admin/payments/</td><td>payment SUCCESS + registration ACTIVE</td><td>duplicate → no-op toast &quot;đã xử lý trước đó&quot;</td></tr><tr><td>Đăng ký phiên (SC-24)</td><td>POST /auctions/{id}/registrations</td><td>mở checkout/hiện bill</td><td>410/403 theo mã → banner tương ứng</td></tr><tr><td>Bid (SC-06)</td><td>POST /auctions/{id}/bids</td><td>feed update + leader badge</td><td>422 highlight min / 409 ended</td></tr><tr><td>Thanh toán order (SC-25)</td><td>POST /orders/{id}/pay</td><td>redirect gateway</td><td>gateway unavailable → manual panel</td></tr><tr><td>Mua gói (SC-07)</td><td>POST /subscriptions/checkout</td><td>redirect → resume → ACTIVE banner</td><td>cancel → về SC-07 giữ context</td></tr><tr><td>Đặt lịch (SC-27)</td><td>POST /housing/{id}/viewing-requests</td><td>PENDING + NTF chủ</td><td>limit/slot → inline</td></tr></tbody></table><h2 id="_6-component-inventory-fe-shared" tabindex="-1">6. Component Inventory (FE shared) <a class="header-anchor" href="#_6-component-inventory-fe-shared" aria-label="Permalink to &quot;6. Component Inventory (FE shared)&quot;">​</a></h2><p><code>Button</code> (variants, loading), <code>Input/Select/DatePicker</code> (+format VND), <code>MoneyText</code>, <code>CountdownTimer</code>, <code>StatusBadge</code> (màu theo enum docs/07 §3), <code>DataTable</code> (server-side), <code>Modal/Drawer</code>, <code>FileUploader</code> (image crop, PDF), <code>BidFeedItem</code>, <code>NotificationBell</code>, <code>EmptyState</code>, <code>ErrorState(+traceId)</code>, <code>SLATag</code>. Đặt tại <code>components/ui/</code>, feature không duplicate.</p><h2 id="_7-design-tokens-cho-design-lead-—-placeholder" tabindex="-1">7. Design Tokens (chờ Design Lead — placeholder) <a class="header-anchor" href="#_7-design-tokens-cho-design-lead-—-placeholder" aria-label="Permalink to &quot;7. Design Tokens (chờ Design Lead — placeholder)&quot;">​</a></h2><p>Primary <code>#0B57D0</code> (đề xuất xanh tin cậy), success <code>#137333</code>, warning <code>#B45309</code>, danger <code>#C5221F</code>, neutral gray scale, radius 8, spacing 4/8/16/24/32. Font: Be Vietnam Pro (display+body). <strong>Cấm dùng emoji icon trong UI production.</strong> Bảng chính thức: Figma variables, map vào Tailwind config khi có.</p><h2 id="_8-đieu-kien-handoff-figma-→-dev-pm-checklist" tabindex="-1">8. Điều kiện Handoff Figma → Dev (PM checklist) <a class="header-anchor" href="#_8-đieu-kien-handoff-figma-→-dev-pm-checklist" aria-label="Permalink to &quot;8. Điều kiện Handoff Figma → Dev (PM checklist)&quot;">​</a></h2><ul><li>[ ] Mọi SC-xx có frame đủ 4 states + chú thích hành vi (copy từ docs/05/03)</li><li>[ ] Spec spacing/tokens export</li><li>[ ] Prototype flow: guest→login-intent, wizard, live page (bid + extend), VIP purchase</li><li>[ ] Dark mode: <strong>không thuộc v1</strong></li><li>[ ] Copy content tiếng Việt final cho: quy chế đấu giá modal, email templates, FAQ điều kiện NOXH (người viết: Ops + Pháp chế duyệt — blocking MS2)</li></ul>`,19)])])}const p=n(i,[["render",o]]);export{g as __pageData,p as default};
